CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'trial' CHECK(status IN ('trial','active','past_due','suspended')), retention_days integer NOT NULL DEFAULT 15 CHECK(retention_days BETWEEN 1 AND 365), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid REFERENCES tenants(id), name text NOT NULL, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('master','owner','operator')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), CHECK ((role='master' AND tenant_id IS NULL) OR (role!='master' AND tenant_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS cameras (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), name text NOT NULL, station text, status text NOT NULL DEFAULT 'unconfigured', stream_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), name text NOT NULL, email text, phone text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS processes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), name text NOT NULL, steps jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), customer_id uuid NOT NULL REFERENCES customers(id), process_id uuid NOT NULL REFERENCES processes(id), camera_id uuid REFERENCES cameras(id), public_token_hash text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','live','paused','completed')), step_index integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, completed_at timestamptz);
CREATE INDEX IF NOT EXISTS idx_orders_tenant ON orders(tenant_id,created_at DESC);
CREATE TABLE IF NOT EXISTS recordings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), order_id uuid NOT NULL REFERENCES orders(id), step_index integer NOT NULL, status text NOT NULL DEFAULT 'pending', storage_key text, started_at timestamptz, ended_at timestamptz);
CREATE TABLE IF NOT EXISTS invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), amount_cents integer NOT NULL CHECK(amount_cents>=0), due_date date NOT NULL, status text NOT NULL DEFAULT 'open', provider_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, tenant_id uuid REFERENCES tenants(id), actor_id uuid REFERENCES users(id), action text NOT NULL, target_type text NOT NULL, target_id text, created_at timestamptz NOT NULL DEFAULT now());